
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EPROMHQ"."PRF_HOTEL_REQUEST_V" ("REQUEST_ID", "MISSION_NAME", "MISSION_ADDRESS", "CHECK_IN", "CHECK_OUT", "CITY_ID", "MISSION_ID", "RESID_ID", "EMP_ID", "TASK_IDS", "UPDATED_BY", "CREATED_AT", "APPROVED", "DELETE_APPROVED", "DELETE_REQUEST_DATE", "LAST_APPROVAL_DATE", "APPROVAL_GM", "EMP_NOTES", "CONFIRMATION_NUMBER", "NOTES_PUBLICRELATION", "HOTEL_NAME", "NIGHT_PRICE", "NUMBER_OF_NIGHTS", "WHATS_APP_NUMBER_PHONE", "RESID_NAME", "CITY_NAME", "MISSION_TYPE", "PR_CHECK_OUT", "PR_CHECK_IN", "REQUEST_TYPE_ID") AS
  SELECT PR."REQUEST_ID",PR."MISSION_NAME",PR."MISSION_ADDRESS",PR."CHECK_IN",PR."CHECK_OUT",PR."CITY_ID",PR."MISSION_ID",PR."RESID_ID",PR."EMP_ID",PR."TASK_IDS",PR."UPDATED_BY",PR."CREATED_AT",PR."APPROVED",PR."DELETE_APPROVED",PR."DELETE_REQUEST_DATE",PR."LAST_APPROVAL_DATE",PR."APPROVAL_GM",PR."EMP_NOTES",PR."CONFIRMATION_NUMBER",PR."NOTES_PUBLICRELATION",PR."HOTEL_NAME",PR."NIGHT_PRICE",PR."NUMBER_OF_NIGHTS",PR."WHATS_APP_NUMBER_PHONE", HR.RESID_NAME, HC.CITY_NAME, HM.MISSION_TYPE, PR_CHECK_OUT,PR_CHECK_IN,PR.REQUEST_TYPE_ID
FROM PRF_HOTEL_REQUEST PR
JOIN PRF_HOTEL_RESIDENCE HR ON HR.RESID_ID = PR.RESID_ID
JOIN PRF_HOTEL_CITIES HC ON PR.CITY_ID = HC.CITY_ID
JOIN PRF_HOTEL_MISSION_TYPES HM ON PR.MISSION_ID = HM.MISSION_ID;
